incorrect:
async function fetchData(userId: string) {
  const user = await fetchUser(userId);
  const posts = await fetchPosts(userId); // Waterfall: waits for fetchUser to finish
  return { user, posts };
}

correct:
async function fetchData(userId: string) {
  const [user, posts] = await Promise.all([
    fetchUser(userId),
    fetchPosts(userId)
  ]);
  return { user, posts };
}
